// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import java.util.ArrayDeque;
import java.util.function.BooleanSupplier;

/**
 * An {@link ApplierScheduler} that runs the applier loop only when a test asks it to. {@link #step()} runs one unit of
 * applier work; {@link #drain()} runs until the applier reports no work. Delayed tasks are collected and fired
 * explicitly with {@link #fireTimers()}, so a test controls every interleaving without threads.
 */
final class SteppingApplierScheduler implements ApplierScheduler {

	private BooleanSupplier runOne;
	private final ArrayDeque<Runnable> timers = new ArrayDeque<>();
	private int wakeups;
	private boolean shutdown;

	@Override
	public void start(BooleanSupplier runOne) {
		this.runOne = runOne;
	}

	@Override
	public void wake() {
		wakeups++;
	}

	@Override
	public void schedule(Runnable task, long delayMillis) {
		timers.addLast(task);
	}

	@Override
	public void shutdown() {
		shutdown = true;
	}

	boolean isShutdown() {
		return shutdown;
	}

	int wakeups() {
		return wakeups;
	}

	/** Runs one unit of applier work; returns whether anything was done. */
	boolean step() {
		return runOne != null && runOne.getAsBoolean();
	}

	/** Runs applier units until the applier reports none left; returns how many ran. */
	int drain() {
		int ran = 0;
		while (step()) {
			ran++;
			if (ran > 100_000) {
				throw new IllegalStateException("applier did not become idle");
			}
		}
		return ran;
	}

	boolean hasTimers() {
		return !timers.isEmpty();
	}

	/** Fires one pending delayed task; returns whether one existed. */
	boolean fireTimer() {
		Runnable timer = timers.pollFirst();
		if (timer == null) {
			return false;
		}
		timer.run();
		return true;
	}

	void fireTimers() {
		while (fireTimer()) {
			// fire every pending timer
		}
	}
}
